# Iterate through the intervals
for k in range(1, 11):
    # Determine if the interval (k-1, k) is positive
    if k % 2 == 0:
        positive_intervals += 1

# The interval (10, infinity) is also positive
positive_intervals += 1

# Print the number of positive intervals
print(positive_intervals)
```
